void Solver::bump_var(int var, double coeff) {
    double inc = var_inc * coeff;
    // Apply a small bonus based on current decision level context
    // Use a non-linear scaling: variables at higher levels get slightly more bump
    if (level[var] > 0) {
        inc *= (1.0 + 0.01 * level[var]);
    }
    if ((activity[var] += inc) > 1e100) {
        for (int i = 1; i <= vars; i++) activity[i] *= 1e-100;
        var_inc *= 1e-100;
    }
    if (vsids.inHeap(var)) vsids.update(var);
}
